14	/// point that wraps the pure `authz::engine::PolicyEngine` with whatever policy/entity
15	/// loading and caching an adapter needs.
16	#[async_trait]
17	pub trait Authorizer: Send + Sync {
18	    async fn is_authorized(&self, req: &AccessRequest) -> Result<Decision, AuthzError>;
19	}
20	
21	/// Persistence port for authored Cedar policies/templates ([`PolicyDocument`]).
22	#[async_trait]
23	pub trait PolicyStore: Send + Sync {
24	    /// One repeatable-read txn (impl detail) — every document is a consistent snapshot.
25	    async fn list_all(&self) -> Result<Vec<PolicyDocument>, AuthzError>;
26	    /// Validates; rejects system-owned documents.
27	    async fn put(&self, doc: &PolicyDocument) -> Result<(), AuthzError>;
28	    /// Rejects system-owned documents.
29	    async fn delete(&self, policy_id: &str) -> Result<(), AuthzError>;
30	    async fn policy_gen(&self) -> Result<u64, AuthzError>;
31	    async fn bump_policy_gen(&self) -> Result<u64, AuthzError>;
32	}
33	
34	/// Persistence port for materialized [`RoleGrant`]s.
35	#[async_trait]
36	pub trait RoleGrantStore: Send + Sync {
37	    /// Inserts the grant row and bumps the policy generation counter.
38	    async fn grant(&self, g: &RoleGrant) -> Result<(), AuthzError>;
39	    async fn revoke(&self, id: Uuid) -> Result<(), AuthzError>;
40	    async fn list_all(&self) -> Result<Vec<RoleGrant>, AuthzError>;
41	    async fn list_by_principal(&self, p: &PrincipalId) -> Result<Vec<RoleGrant>, AuthzError>;
42	    /// Looks up a single grant by id — `None` if it was never granted or has since been
43	    /// revoked. `RoleService::revoke` (SMA-444 Task 17) uses this to resolve the grant's
44	    /// `GrantScope` before authorizing the revoke itself against it.
45	    async fn find(&self, id: Uuid) -> Result<Option<RoleGrant>, AuthzError>;
46	}
47	
48	/// Loads the minimal [`EntitySlice`] needed to decide one request (principal, resource,
49	/// ancestor chain, synthetic `Root`).
50	#[async_trait]
51	pub trait EntitySliceLoader: Send + Sync {
52	    async fn load(&self, resource: &Prn, principal: &Prn) -> Result<EntitySlice, AuthzError>;
53	    async fn entity_gen(&self) -> Result<u64, AuthzError>;
54	}
55	
56	/// Caches previously-computed [`Decision`]s, keyed by the adapter's own cache-key scheme
57	/// (e.g. request + policy/entity generation).
58	#[async_trait]
59	pub trait DecisionCache: Send + Sync {
60	    async fn get(&self, key: &str) -> Option<Decision>;
61	    async fn put(&self, key: &str, decision: &Decision);
62	}
63	
64	/// Records an [`AuthzDecisionEvent`] for audit.
65	#[async_trait]
66	pub trait AuditSink: Send + Sync {
67	    async fn record(&self, ev: &AuthzDecisionEvent);
68	}
69	
