71	mod tests {
72	    use super::*;
73	
74	    // Compile-time proof the authz ports are object-safe (injected as trait objects).
75	    #[allow(dead_code)]
76	    fn assert_object_safe(_: &dyn Authorizer, _: &dyn PolicyStore, _: &dyn RoleGrantStore, _: &dyn EntitySliceLoader, _: &dyn DecisionCache, _: &dyn AuditSink) {}
