66	/// The `determining_policies` marker for the fail-closed `Deny` `is_authorized` returns when
67	/// the entity-slice loader reports the request's resource doesn't exist (SMA-444 review fix)
68	/// — mirrors `authz::engine::DEFAULT_DENY_MARKER`'s role as a synthetic, non-Cedar-policy-id
69	/// diagnostic string.
70	pub const RESOURCE_NOT_FOUND_MARKER: &str = "resource-not-found";
