72	/// Abstraction over "read the two authz generation counters", so `CedarAuthorizer` can be
73	/// exercised against a fake that errors (simulating a `Generations::Redis` outage) without
74	/// any real Redis connection in a unit test. [`Generations`] (Task 10's concrete
75	/// memory/redis backend) implements this directly below, so production callers just wrap a
76	/// plain `Generations` in an `Arc`.
77	#[async_trait]
78	pub trait GenerationsReader: Send + Sync {
79	    async fn policy_gen(&self) -> Result<u64, AuthzError>;
80	    async fn entity_gen(&self) -> Result<u64, AuthzError>;
81	}
