94	/// The `Authorizer` port's implementation (ADR-0013): composes a [`PolicySnapshot`] (the
95	/// authoritative compiled policy set), an [`EntitySliceLoader`] (typically `SliceCache`
96	/// wrapping a Postgres-backed loader), a [`DecisionCache`] accelerator, the
97	/// [`GenerationsReader`] the cache key is derived from, and an [`AuditSink`]. Not `Clone` —
98	/// callers share ONE instance across every `AppState` clone via `Arc<CedarAuthorizer>`
99	/// (mirroring `PolicySnapshot`'s own Arc-sharing posture).
100	pub struct CedarAuthorizer {
101	    snapshot: Arc<PolicySnapshot>,
102	    slices: Arc<dyn EntitySliceLoader>,
103	    decisions: Arc<dyn DecisionCache>,
104	    gens: Arc<dyn GenerationsReader>,
105	    audit: Arc<dyn AuditSink>,
106	}
107	
108	impl CedarAuthorizer {
109	    #[must_use]
110	    pub fn new(snapshot: Arc<PolicySnapshot>, slices: Arc<dyn EntitySliceLoader>, decisions: Arc<dyn DecisionCache>, gens: Arc<dyn GenerationsReader>, audit: Arc<dyn AuditSink>) -> Self {
111	        Self {
112	            snapshot,
113	            slices,
114	            decisions,
115	            gens,
116	            audit,
117	        }
118	    }
119	
120	    /// Reads the entity generation counter and completes the decision-cache key iff it
121	    /// succeeds (D11/D12 fail-open): an error (a Redis outage) is logged and mapped to
122	    /// `None` — the caller then skips the cache entirely for this call rather than caching
123	    /// under a partial/guessed key. `policy_gen` is deliberately NOT read here (nor anywhere
124	    /// else in this module) — the key's policy component is always `compiled_gen`, the
125	    /// `r#gen` of the exact [`CompiledPolicies`] snapshot the caller evaluated, so the key
126	    /// and the evaluated policy set can never drift apart.
127	    async fn cache_key(&self, compiled_gen: u64, req: &AccessRequest) -> Option<String> {
128	        match self.gens.entity_gen().await {
129	            Ok(entity_gen) => Some(decision_key(compiled_gen, entity_gen, req)),
130	            Err(err) => {
131	                tracing::warn!(error = %err, "cedar_authorizer: entity generation counter unreadable — bypassing the decision cache for this call (fail-open, D11/D12)");
132	                None
133	            }
134	        }
135	    }
136	}
