138	#[async_trait]
139	impl Authorizer for CedarAuthorizer {
140	    async fn is_authorized(&self, req: &AccessRequest) -> Result<Decision, AuthzError> {
141	        // Step 1 (AC1): best-effort synchronous staleness reload. A reload error never fails
142	        // the decision — it just means this call evaluates against the last-known-good
143	        // snapshot rather than a fresher one.
144	        if let Err(err) = self.snapshot.reload_if_stale().await {
145	            tracing::warn!(error = %err, "cedar_authorizer: policy snapshot reload_if_stale failed — deciding against the last-known-good snapshot");
146	        }
147	
148	        // Step 2: read the snapshot that will actually be evaluated FIRST. `compiled.r#gen`
149	        // is the authoritative policy generation this call decides against, and it's the
150	        // source of the decision-cache key's policy component below — never a second,
151	        // independently-timed `Generations::policy_gen()` read.
152	        let compiled = self.snapshot.current().await;
153	
154	        // Step 3: fail-open cache lookup, keyed off `compiled.r#gen` (not a fresh
155	        // `policy_gen()` read) plus the entity generation.
156	        let cache_key = self.cache_key(compiled.r#gen, req).await;
157	        if let Some(key) = &cache_key
158	            && let Some(cached) = self.decisions.get(key).await
159	        {
160	            // A cache hit was already audited on the miss that populated it — auditing again
161	            // here would double-record the same decision.
162	            return Ok(cached);
163	        }
164	
165	        // Step 4: the authoritative path — always runs on a miss OR a bypassed cache. Uses
166	        // the SAME `compiled` snapshot read in step 2, so the policy set evaluated here can
167	        // never be a different generation than the one the cache key (step 3) was minted
168	        // from. `ResourceNotFound` is caught and turned into a fail-closed `Deny` — never a
169	        // 500, and never an existence oracle — while every other slice-load error (a genuine
170	        // backend failure) still propagates unchanged.
171	        let decision = match self.slices.load(&req.resource, &req.principal).await {
172	            Ok(slice) => PolicyEngine::decide(&compiled.policy_set, &slice, req),
173	            Err(AuthzError::ResourceNotFound(_)) => Decision {
174	                effect: Effect::Deny,
175	                determining_policies: vec![RESOURCE_NOT_FOUND_MARKER.to_string()],
176	            },
177	            Err(err) => return Err(err),
178	        };
179	
180	        // Step 5: audit every decision this method actually computes (never on a cache hit).
181	        let event = AuthzDecisionEvent {
182	            principal_prn: req.principal.canonical(),
183	            action: req.action.as_wire().to_string(),
184	            resource_prn: req.resource.canonical(),
185	            effect: decision.effect,
186	            determining_policies: decision.determining_policies.clone(),
187	            at: chrono::Utc::now(),
188	        };
189	        self.audit.record(&event).await;
190	
191	        // Step 6: best-effort populate the cache (only if step 3 minted a key).
192	        if let Some(key) = cache_key {
193	            self.decisions.put(&key, &decision).await;
194	        }
195	
196	        Ok(decision)
197	    }
198	}
