3	//! Postgres-backed `PrincipalRepository` (SeaORM). Maps domain <-> entity models and
4	//! backend errors into the core's `RepositoryError`.
5	
6	use super::entities::{principal, user};
7	use super::map_err;
8	use async_trait::async_trait;
9	use paigasus_iam_core::{Email, Principal, PrincipalId, PrincipalKind, PrincipalRepository, PrincipalStatus, RepositoryError, User};
10	use paigasus_kernel::Prn;
11	use sea_orm::{ActiveModelTrait, DatabaseConnection, EntityTrait, Set, TransactionTrait};
12	
13	// `Clone` lets the composition root (`http::AppState::new`) hold a repo handle inside a
14	// `#[derive(Clone)] CreateUser` — cheap, `DatabaseConnection` clones an `Arc`-backed pool
15	// handle, not a connection.
16	#[derive(Clone)]
17	pub struct PgPrincipalRepository {
18	    db: DatabaseConnection,
19	}
20	
21	impl PgPrincipalRepository {
22	    #[must_use]
23	    pub fn new(db: DatabaseConnection) -> Self {
24	        PgPrincipalRepository { db }
25	    }
26	}
27	
28	/// Maps a `principal` row to the domain `Principal` (PRN/kind/status parsing, each
29	/// failure wrapped as a backend error) — the shared half of `find_user`/`find_principal`.
30	fn map_principal_row(pm: principal::Model) -> Result<Principal, RepositoryError> {
31	    let prn = Prn::parse(&pm.prn).map_err(|e| RepositoryError::Backend(Box::new(std::io::Error::other(e.to_string()))))?;
32	    let pid = PrincipalId::from_prn(prn);
33	    let kind = PrincipalKind::parse(&pm.kind).ok_or_else(|| RepositoryError::Backend(Box::new(std::io::Error::other("bad kind"))))?;
34	    let status = PrincipalStatus::parse(&pm.status).ok_or_else(|| RepositoryError::Backend(Box::new(std::io::Error::other("bad status"))))?;
35	    Ok(Principal::new(pid, kind, status, pm.created_at, pm.updated_at))
36	}
37	
38	#[async_trait]
39	impl PrincipalRepository for PgPrincipalRepository {
