3	//! `RoleService`: grant/revoke/list role-grant management use cases (SMA-444 Task 17,
4	//! ADR-0013). `grant` enforces the anti-escalation invariant — only an actor who may already
5	//! `GrantRole` AT the target scope itself (Root, or a tenancy node) may grant a role there,
6	//! so a principal can never bootstrap authority it doesn't already hold. `list`'s exposure
7	//! rule is a deliberate M3 simplification: self is always visible, anyone else's grants
8	//! require platform-level (`Root`-scoped) `ListRoleGrants` — see [`RoleService::list`]'s doc.
9	//!
10	//! **SMA-444 cross-tenant-escalation fix (defense-in-depth):** `parse_grant_scope` builds a
11	//! `TenancyNodeRef` straight from the caller's raw `scope_prn` string, whose org slot
12	//! `TenancyNodeRef::from_prn` only checks is PRESENT, never that it's CORRECT
13	//! (`tenancy::check`) — a team/project scope can name a real node's uuid paired with an
14	//! arbitrary org uuid. The root-cause fix lives in `PgEntitySliceLoader` (the `Team` branch
15	//! now parents on the node's REAL stored org, never the caller's PRN), which alone closes the
16	//! escalation for every decision path. `grant` additionally calls [`RoleService::resolve_scope`]
17	//! before persisting: it re-resolves the scope node against the DB and rejects a caller PRN
18	//! that doesn't byte-match the node's real canonical PRN — mirroring the forged-org-slot
19	//! defense `PgMembershipRepository::attach`/`InMemoryMemberships::attach` already apply to a
20	//! membership's `node_prn` (`RepositoryError::PrnMismatch`). Without this, a grant made by an
21	//! actor who legitimately holds authority over the node's REAL parent could still persist a
22	//! `RoleGrant` whose `scope.canonical_prn()` misrepresents that parent — a data-integrity gap
23	//! this closes, on top of (not instead of) the entity-slice loader's own fix.
24	
25	use crate::application::authorize::Authorize;
26	use crate::application::error::TenancyError;
27	use paigasus_iam_core::authz::model::root_prn;
28	use paigasus_iam_core::authz::roles as authz_roles;
29	use paigasus_iam_core::{Action, Clock, GrantScope, IdGenerator, OrganizationRepository, PrincipalId, ProjectRepository, RoleGrant, RoleGrantStore, TeamRepository, TenancyNodeRef};
30	use paigasus_kernel::Prn;
31	use std::sync::Arc;
32	use uuid::Uuid;
33	
34	/// Parses a raw principal PRN string: must be syntactically valid (else `InvalidPrn` with the
35	/// kernel's stable error-kind token), and must be service `"iam"`, resource type
36	/// `"principal"` (else `InvalidPrn` with the PRN's canonical form). Mirrors
37	/// `application::memberships::parse_principal_prn` — duplicated rather than shared across
38	/// modules (a five-line pure parse, not worth a visibility change on an unrelated file).
39	fn parse_principal_prn(raw: &str) -> Result<PrincipalId, TenancyError> {
40	    let prn = Prn::parse(raw).map_err(|e| TenancyError::InvalidPrn(e.kind().to_owned()))?;
41	    if prn.service() != "iam" || prn.resource_type() != "principal" {
42	        return Err(TenancyError::InvalidPrn(prn.canonical()));
43	    }
44	    Ok(PrincipalId::from_prn(prn))
45	}
46	
47	/// Parses a raw grant-scope PRN string into a [`GrantScope`]: the synthetic Root sentinel's
48	/// own canonical PRN maps to `GrantScope::Root`; anything else must parse as a tenancy-node
49	/// PRN (`TenancyNodeRef::from_prn`, whose `DomainError` auto-converts to `TenancyError::
50	/// InvalidPrn`) and becomes `GrantScope::Node`.
51	fn parse_grant_scope(raw: &str) -> Result<GrantScope, TenancyError> {
52	    if raw == root_prn().canonical() {
53	        return Ok(GrantScope::Root);
54	    }
55	    let prn = Prn::parse(raw).map_err(|e| TenancyError::InvalidPrn(e.kind().to_owned()))?;
56	    Ok(GrantScope::Node(TenancyNodeRef::from_prn(prn)?))
57	}
58	
59	/// The `Prn` a [`GrantScope`] represents as an authorization *resource* — `root_prn()` for
60	/// `Root`, or the tenancy node's own PRN. This is what `grant`/`revoke` authorize the actor
61	/// against: the scope node itself, not the grant's target principal (the anti-escalation
62	/// invariant — see module docs).
63	fn scope_resource_prn(scope: &GrantScope) -> Prn {
64	    match scope {
65	        GrantScope::Root => root_prn(),
66	        GrantScope::Node(TenancyNodeRef::Organization(id)) => id.prn().clone(),
67	        GrantScope::Node(TenancyNodeRef::Team(id)) => id.prn().clone(),
68	        GrantScope::Node(TenancyNodeRef::Project(id)) => id.prn().clone(),
69	    }
70	}
71	
72	/// Role-grant lifecycle use cases. `grants` is `Arc<dyn RoleGrantStore>` (not generic-DI) —
73	/// it's the same shared handle `AppState` composes into `PolicySnapshot`, so a later task's
74	/// wiring clones one `Arc` rather than standing up a second store instance. `orgs`/`teams`/
75	/// `projects` are likewise `Arc<dyn ...>` trait objects (SMA-444 cross-tenant-escalation fix,
76	/// module docs) — [`RoleService::resolve_scope`]'s own DB-lookup defense, independent of
77	/// `grants`. `ids`/`clock` stay generic-DI, mirroring `MembershipService`.
78	#[derive(Clone)]
79	pub struct RoleService<I, C> {
80	    grants: Arc<dyn RoleGrantStore>,
81	    orgs: Arc<dyn OrganizationRepository>,
82	    teams: Arc<dyn TeamRepository>,
83	    projects: Arc<dyn ProjectRepository>,
84	    authorize: Authorize,
85	    ids: I,
86	    clock: C,
87	}
88	
89	impl<I, C> RoleService<I, C>
90	where
91	    I: IdGenerator,
92	    C: Clock,
93	{
94	    pub fn new(
95	        grants: Arc<dyn RoleGrantStore>,
96	        orgs: Arc<dyn OrganizationRepository>,
97	        teams: Arc<dyn TeamRepository>,
98	        projects: Arc<dyn ProjectRepository>,
99	        authorize: Authorize,
100	        ids: I,
101	        clock: C,
102	    ) -> Self {
103	        Self {
104	            grants,
105	            orgs,
106	            teams,
107	            projects,
108	            authorize,
109	            ids,
110	            clock,
111	        }
112	    }
113	
114	    /// Resolves `scope`'s tenancy node against the DB and confirms the caller-supplied PRN
115	    /// byte-matches its REAL, stored canonical PRN — `GrantScope::Root` has no forgeable slot
116	    /// and is a no-op. `NotFound` if the node doesn't exist; `PrnMismatch` if it does but the
117	    /// caller's org slot doesn't match the stored one (module docs).
118	    async fn resolve_scope(&self, scope: &GrantScope) -> Result<(), TenancyError> {
119	        let (claimed, stored) = match scope {
120	            GrantScope::Root => return Ok(()),
121	            GrantScope::Node(TenancyNodeRef::Organization(id)) => {
122	                let view = self.orgs.find(id.uuid()).await?.ok_or(TenancyError::NotFound)?;
123	                (id.canonical(), view.node.id.canonical())
124	            }
125	            GrantScope::Node(TenancyNodeRef::Team(id)) => {
126	                let view = self.teams.find(id.uuid()).await?.ok_or(TenancyError::NotFound)?;
127	                (id.canonical(), view.node.id.canonical())
128	            }
129	            GrantScope::Node(TenancyNodeRef::Project(id)) => {
130	                let view = self.projects.find(id.uuid()).await?.ok_or(TenancyError::NotFound)?;
131	                (id.canonical(), view.node.id.canonical())
132	            }
133	        };
134	        if claimed != stored {
135	            return Err(TenancyError::PrnMismatch);
136	        }
137	        Ok(())
138	    }
139	
140	    /// Grants `role_key` to `principal_prn` at `scope_prn`. Order of checks: (1) the
141	    /// principal PRN parses; (2) `role_key` names a known system role (else `UnknownRole`);
142	    /// (3) `scope_prn` parses into a `GrantScope`; (4) the scope's `NodeKind` is one the role
143	    /// allows (else `InvalidScope` — e.g. granting an `Organization`-scoped role at a
144	    /// `Team`); (5) **the anti-escalation check**: `actor` must itself be authorized for
145	    /// `Action::GrantRole` AT the scope (the scope node is the resource, not the target
146	    /// principal) — only someone who already has authority there may hand more of it out; the
147	    /// scope's Cedar identity is derived from its REAL tenancy ancestry regardless of a forged
148	    /// PRN (the entity-slice loader's own root-cause fix, SMA-444 cross-tenant-escalation
149	    /// fix), so a forged-org-slot escalation attempt is denied HERE, `Forbidden`; (6)
150	    /// [`RoleService::resolve_scope`] re-resolves the scope node against the DB and rejects a
151	    /// scope PRN that doesn't byte-match the node's real canonical form (else
152	    /// `NotFound`/`PrnMismatch` — defense-in-depth against persisting a grant whose stored
153	    /// scope misrepresents its real tenancy, module docs), run only once `actor` is already
154	    /// authorized so the anti-escalation check above is what a forged-but-unauthorized attempt
155	    /// actually trips. Only after all six succeed is the grant minted and persisted.
156	    pub async fn grant(&self, actor: &Prn, principal_prn: &str, role_key: &str, scope_prn: &str) -> Result<RoleGrant, TenancyError> {
157	        let principal = parse_principal_prn(principal_prn)?;
158	        let role = authz_roles::role(role_key).ok_or_else(|| TenancyError::UnknownRole(role_key.to_string()))?;
159	        let scope = parse_grant_scope(scope_prn)?;
160	        if !role.scope_kinds.contains(&scope.kind()) {
161	            return Err(TenancyError::InvalidScope(scope_prn.to_string()));
162	        }
163	
164	        self.authorize.check(actor, Action::GrantRole, &scope_resource_prn(&scope)).await?;
165	        self.resolve_scope(&scope).await?;
166	
167	        let id = self.ids.new_membership_id();
168	        let now = self.clock.now();
169	        let grant = RoleGrant {
170	            id,
171	            principal,
172	            role_key: role.key,
173	            scope,
174	            linked_policy_id: format!("grant:{id}"),
175	            created_at: now,
176	        };
177	        self.grants.grant(&grant).await?;
178	        Ok(grant)
179	    }
180	
181	    /// Revokes a grant by id. `NotFound` if it doesn't exist (or was already revoked).
182	    /// Authorizes `actor` for `Action::RevokeRole` against the EXISTING grant's own scope —
183	    /// mirrors `grant`'s anti-escalation posture: revoking requires the same authority
184	    /// granting there would.
185	    pub async fn revoke(&self, actor: &Prn, id: Uuid) -> Result<(), TenancyError> {
186	        let grant = self.grants.find(id).await?.ok_or(TenancyError::NotFound)?;
187	        self.authorize.check(actor, Action::RevokeRole, &scope_resource_prn(&grant.scope)).await?;
188	        Ok(self.grants.revoke(id).await?)
189	    }
190	
191	    /// Lists every grant held by `principal_prn`. Exposure rule (M3 simplification — a full
192	    /// per-scope visibility model is out of scope here): an actor may always list their OWN
193	    /// grants, no policy check needed; listing anyone ELSE's requires `Action::ListRoleGrants`
194	    /// authorized against `root_prn()` — under Cedar's `resource in ?resource` semantics only
195	    /// a `Root`-scoped grant (`platform_admin`) satisfies a `Root`-resource check, so this is
196	    /// effectively "self, or a platform admin."
197	    pub async fn list(&self, actor: &Prn, principal_prn: &str) -> Result<Vec<RoleGrant>, TenancyError> {
198	        let principal = parse_principal_prn(principal_prn)?;
199	        if actor.canonical() != principal.canonical() {
200	            self.authorize.check(actor, Action::ListRoleGrants, &root_prn()).await?;
201	        }
202	        Ok(self.grants.list_by_principal(&principal).await?)
203	    }
204	}
