223	    /// ever reaches `resolve_scope` with `GrantScope::Root` (a no-op) or gets rejected before
224	    /// `resolve_scope` even runs (e.g. `grant_rejects_a_disallowed_scope_kind`'s scope-kind
225	    /// check, which — by construction — happens BEFORE `resolve_scope` in `grant`'s check
226	    /// order) — see `new_service_with_store` for scenarios that need real seeded nodes.
227	    fn new_service(fake: FakeAuthorizer) -> RoleService<SeqIds, FixedClock> {
228	        new_service_with_store(fake, TenancyStore::default())
229	    }
