231	    /// Like `new_service`, but over a caller-supplied `TenancyStore` — for scenarios (SMA-444
232	    /// cross-tenant-escalation fix) that need `resolve_scope`'s DB lookup to see real seeded
233	    /// org/team/project rows.
234	    fn new_service_with_store(fake: FakeAuthorizer, store: TenancyStore) -> RoleService<SeqIds, FixedClock> {
235	        RoleService::new(
236	            Arc::new(InMemoryRoleGrants::default()),
237	            Arc::new(InMemoryOrgs(store.clone())),
238	            Arc::new(InMemoryTeams(store.clone())),
239	            Arc::new(InMemoryProjects(store)),
240	            Authorize::new(Arc::new(fake)),
241	            SeqIds::default(),
242	            FixedClock::default(),
243	        )
244	    }
