246	    #[tokio::test]
247	    async fn grant_rejects_an_unknown_role() {
248	        let svc = new_service(FakeAuthorizer::default());
249	        let actor = principal_prn(1);
250	        let err = svc.grant(&actor, &principal_prn(2).canonical(), "no-such-role", &root_prn().canonical()).await.unwrap_err();
251	        assert_eq!(err, TenancyError::UnknownRole("no-such-role".to_string()));
252	    }
253	
254	    #[tokio::test]
255	    async fn grant_rejects_a_disallowed_scope_kind() {
256	        // `platform_admin` only allows `NodeKind::Root` — an organization scope must be
257	        // rejected even before the authorizer is ever consulted.
258	        let svc = new_service(FakeAuthorizer::default());
259	        let actor = principal_prn(1);
260	        let err = svc.grant(&actor, &principal_prn(2).canonical(), "platform_admin", &org_prn(100).canonical()).await.unwrap_err();
261	        assert_eq!(err, TenancyError::InvalidScope(org_prn(100).canonical()));
262	    }
263	
264	    #[tokio::test]
265	    async fn grant_denies_an_unauthorized_actor() {
266	        // The authorizer never allows `GrantRole` at `Root` — the actor lacks the authority
267	        // to grant there, so the grant must be denied before ever touching the store.
268	        let svc = new_service(FakeAuthorizer::default());
269	        let actor = principal_prn(1);
270	        let err = svc.grant(&actor, &principal_prn(2).canonical(), "platform_admin", &root_prn().canonical()).await.unwrap_err();
271	        assert_eq!(err, TenancyError::Forbidden);
272	    }
273	
274	    #[tokio::test]
275	    async fn grant_succeeds_for_an_authorized_actor() {
276	        let fake = FakeAuthorizer::default();
277	        fake.allow(Action::GrantRole, &root_prn());
278	        let svc = new_service(fake);
279	        let actor = principal_prn(1);
280	        let target = principal_prn(2);
281	
282	        let grant = svc.grant(&actor, &target.canonical(), "platform_admin", &root_prn().canonical()).await.unwrap();
283	        assert_eq!(grant.role_key, "platform_admin");
284	        assert_eq!(grant.scope, GrantScope::Root);
285	        assert_eq!(grant.linked_policy_id, format!("grant:{}", grant.id));
286	
287	        let listed = svc.list(&target, &target.canonical()).await.unwrap();
288	        assert_eq!(listed, vec![grant]);
289	    }
290	
291	    /// SMA-444 cross-tenant-escalation fix (FIX 2, defense-in-depth): `resolve_scope` must
292	    /// reject a team-scope PRN whose org slot doesn't match the team's REAL stored org, even
293	    /// though `TenancyNodeRef::from_prn` happily parses it (it only checks an org slot is
294	    /// PRESENT, never that it's correct — `tenancy::check`) and even when the authorizer would
295	    /// otherwise ALLOW the grant. Without this check, `grant` would return `Forbidden` (the
296	    /// always-deny-by-default fake never having been told to allow anything) rather than
297	    /// `PrnMismatch` — so asserting `PrnMismatch` specifically here proves `resolve_scope` ran
298	    /// and rejected the forgery BEFORE the authorizer was ever consulted, not merely that SOME
299	    /// check happened to deny it. This test fails (`Forbidden`, not `PrnMismatch`) without FIX
300	    /// 2's `resolve_scope` call in `grant`.
301	    #[tokio::test]
302	    async fn grant_rejects_a_team_scope_with_a_forged_org_slot_even_when_the_authorizer_would_allow() {
303	        let store = TenancyStore::default();
304	        let now = Utc.timestamp_opt(0, 0).unwrap();
305	        let real_org = Uuid::from_u128(500);
306	        let wrong_org = Uuid::from_u128(501);
307	        let team_uuid = Uuid::from_u128(502);
308	        store
309	            .orgs
310	            .lock()
311	            .unwrap()
312	            .insert(real_org, Organization::new(OrganizationId::from_uuid(real_org), Slug::parse("acme").unwrap(), "Acme", now).unwrap());
313	        store
314	            .teams
315	            .lock()
316	            .unwrap()
317	            .insert(team_uuid, Team::new(TeamId::from_parts(real_org, team_uuid), Slug::parse("eng").unwrap(), "Eng", now).unwrap());
318	
319	        // The forged scope PRN the caller submits: `team_uuid`'s REAL uuid, but `wrong_org`'s
320	        // uuid in the org slot (the team really lives under `real_org`).
321	        let forged_team = TeamId::from_parts(wrong_org, team_uuid);
322	
323	        let fake = FakeAuthorizer::default();
