3	//! `ApiKeyService`: API-key lifecycle use cases — issue/revoke/list (SMA-445 Task 17). Mirrors
4	//! `RoleService`/`ServiceAccountService`'s DI + authorize pattern (`application/roles.rs:78-204`,
5	//! `application/service_accounts.rs:63-143`): every method authorizes BEFORE mutating/reading.
6	//!
7	//! **D15 anti-escalation (THE security-critical invariant of this file, spec D15):** an API key
8	//! is a bearer credential for its service account's ENTIRE current grant set — whoever holds the
9	//! plaintext token wields every `RoleGrant` the SA has at the moment of use (`AuthenticateApiKey`,
10	//! Task 18, resolves the token straight to the SA's principal; Cedar then evaluates against
11	//! whatever grants that principal holds). So minting a key must never let an actor obtain
12	//! authority THEY could not already grant directly. [`ApiKeyService::issue`] enforces this by
13	//! mirroring [`crate::application::roles::RoleService::grant`]'s own anti-escalation check
14	//! ("you can only grant what you already hold" — `roles.rs:140-155`) once PER GRANT the target
15	//! SA currently holds: `actor` must be authorized for `Action::IssueApiKey` AT the SA's owner
16	//! node (the ordinary "may this actor manage this SA's keys at all" check, mirroring
17	//! `ServiceAccountService`'s `owner_resource_prn` posture) **AND**, for every one of the SA's
18	//! `RoleGrant`s (fetched via `grants: Arc<dyn RoleGrantStore>::list_by_principal`, exactly how
19	//! `RoleService` shares the same store — module docs there), `Action::GrantRole` AT that grant's
20	//! own scope. A single denied grant anywhere in the SA's grant set fails the WHOLE issuance,
21	//! `Forbidden`, before any id is minted or secret generated — an actor who could not grant even
22	//! ONE of the SA's roles to a third party must not be able to mint a key that wields all of them.
23	//!
24	//! **Deliberately not gated on status (mirrors Task 16's own `entity_gen` deferral):**
25	//! `issue`/`revoke`/`list` all look up the service account via `ServiceAccountRepository::find`,
26	//! which — since the SMA-445 PR's CodeRabbit fix surfacing SA status to callers — now returns a
27	//! `ServiceAccountRecord` carrying the underlying `Principal`'s lifecycle status alongside the
28	//! account (D16: status still lives on `Principal`, never on `ServiceAccount`, so `find`'s
29	//! signature is a join-read, not a stored field). This service still never READS that `status`
30	//! field, on purpose: no current Cedar policy reads `principal.status`, and a disabled SA is
31	//! already blocked twice over without a check here — `ServiceAccountService::archive`'s own
32	//! cache-evict step (any key already cached as valid stops authenticating immediately), plus
33	//! Task 18's `AuthenticateApiKey`, which checks `PrincipalStatus` at authentication time on every
34	//! request regardless of what `issue` did or didn't check at mint time. Issuing a key to an
35	//! already-disabled SA is therefore harmless (the key is simply unusable until/unless the SA is
36	//! ever re-enabled) rather than a security hole — gating `issue` on it here would be a redundant
37	//! belt-and-braces check outside this task's declared file list (`src/application/api_keys.rs` +
38	//! `application/mod.rs`).
39	
40	use crate::adapters::api_keys::ApiKeyValidationCache;
41	use crate::application::authorize::Authorize;
42	use crate::application::error::TenancyError;
43	use crate::application::pagination::Page;
44	use crate::config::ApiKeyConfig;
45	use chrono::{DateTime, Duration, Utc};
46	use paigasus_iam_core::authz::model::root_prn;
47	use paigasus_iam_core::{
48	    Action, ApiKey, ApiKeyId, ApiKeyRepository, ApiKeyStatus, Clock, GrantScope, IdGenerator, KeyEntropy, NewApiKey, PrincipalId, RoleGrantStore, SecretHasher, ServiceAccountRepository,
49	    TenancyNodeRef, display_prefix, format_token,
50	};
51	use paigasus_kernel::Prn;
52	use std::sync::Arc;
53	
54	/// The `Prn` a tenancy node represents as an authorization *resource* — mirrors
55	/// `roles.rs::scope_resource_prn`'s / `service_accounts.rs::owner_resource_prn`'s node arms
56	/// exactly. Shared by [`owner_resource_prn`] (a service account's owner is always a concrete
57	/// node, `ck_service_account_owner`, no `Root` arm) and [`grant_scope_resource_prn`] (a
58	/// `RoleGrant`'s scope CAN be `Root`, handled separately there).
59	fn node_resource_prn(node: &TenancyNodeRef) -> Prn {
60	    match node {
61	        TenancyNodeRef::Organization(id) => id.prn().clone(),
62	        TenancyNodeRef::Team(id) => id.prn().clone(),
63	        TenancyNodeRef::Project(id) => id.prn().clone(),
64	    }
65	}
66	
67	/// The `Prn` a service account's owner node represents as an authorization *resource* —
68	/// identical in shape to `service_accounts.rs::owner_resource_prn` (duplicated rather than
69	/// made `pub(crate)` across an unrelated module, mirroring `roles.rs::parse_principal_prn`'s
70	/// own "not worth a visibility change" doc rationale for a five-line pure helper).
71	fn owner_resource_prn(owner: &TenancyNodeRef) -> Prn {
72	    node_resource_prn(owner)
73	}
74	
75	/// The `Prn` a `RoleGrant`'s scope represents as an authorization *resource* — mirrors
76	/// `roles.rs::scope_resource_prn` exactly (duplicated for the same reason as
77	/// [`owner_resource_prn`] above): `root_prn()` for `GrantScope::Root`, else the tenancy node's
78	/// own PRN. This is what [`ApiKeyService::issue`]'s D15 check authorizes `actor` against for
79	/// EACH of the target SA's grants.
80	fn grant_scope_resource_prn(scope: &GrantScope) -> Prn {
81	    match scope {
82	        GrantScope::Root => root_prn(),
83	        GrantScope::Node(node) => node_resource_prn(node),
84	    }
85	}
86	
87	/// API-key lifecycle use cases. `grants`/`cache` are shared `Arc<dyn ...>` handles — `grants`
88	/// is the same store handle `RoleService` holds (module docs there: a later task's `AppState`
89	/// wiring clones one `Arc` rather than standing up a second store instance), `cache` is the
90	/// same `ApiKeyValidationCache` handle `ServiceAccountService::archive` evicts through.
91	/// `keys`/`service_accounts`/`ids`/`clock` stay generic-DI, mirroring `ServiceAccountService`'s
92	/// `repo`. `hasher`/`entropy` are the SMA-445 Task 5 ports (`SecretHasher`/`KeyEntropy`),
93	/// generic-DI so unit tests can inject deterministic fakes instead of the real
94	/// `HmacSecretHasher`/`OsRngKeyEntropy` adapters (which need a real `Pepper`/OS CSPRNG). `config`
95	/// carries the SMA-445 Task 15 `[api_keys]` block wholesale (`key_prefix`, `default_expiry_days`
96	/// are the only fields this service reads) rather than a bespoke subset struct, so a future
97	/// `AppState` wiring can pass `iam_config.api_keys.clone()` directly.
98	#[derive(Clone)]
99	pub struct ApiKeyService<K, S, I, C, H, E> {
100	    keys: K,
101	    service_accounts: S,
102	    grants: Arc<dyn RoleGrantStore>,
103	    authorize: Authorize,
104	    hasher: H,
105	    entropy: E,
106	    cache: Arc<dyn ApiKeyValidationCache>,
107	    ids: I,
108	    clock: C,
109	    config: ApiKeyConfig,
110	}
111	
112	impl<K, S, I, C, H, E> ApiKeyService<K, S, I, C, H, E>
113	where
114	    K: ApiKeyRepository,
115	    S: ServiceAccountRepository,
116	    I: IdGenerator,
117	    C: Clock,
118	    H: SecretHasher,
119	    E: KeyEntropy,
120	{
121	    #[allow(clippy::too_many_arguments)]
122	    pub fn new(
123	        keys: K,
124	        service_accounts: S,
125	        grants: Arc<dyn RoleGrantStore>,
126	        authorize: Authorize,
127	        hasher: H,
128	        entropy: E,
129	        cache: Arc<dyn ApiKeyValidationCache>,
130	        ids: I,
131	        clock: C,
132	        config: ApiKeyConfig,
133	    ) -> Self {
134	        Self {
135	            keys,
136	            service_accounts,
137	            grants,
138	            authorize,
139	            hasher,
140	            entropy,
141	            cache,
142	            ids,
143	            clock,
144	            config,
145	        }
146	    }
147	
148	    /// Issues a new API key for `sa_id`. Order of checks (D15, module docs — the
149	    /// SECURITY-CRITICAL part of this file):
150	    ///
151	    /// 1. The service account must exist (`NotFound` if absent).
152	    /// 2. `actor` must be authorized for `Action::IssueApiKey` AT the SA's owner node.
153	    /// 3. For EVERY `RoleGrant` the SA currently holds (`grants.list_by_principal`), `actor`
154	    ///    must ALSO be authorized for `Action::GrantRole` AT that grant's own scope — any single
155	    ///    denial fails the whole call, `Forbidden`, before anything is minted.
156	    ///
157	    /// Only once both authorization checks fully pass does this mint an id, generate a secret
158	    /// (`entropy.new_secret()`), hash it (`hasher.hash`), and persist the `ApiKey` row together
159	    /// with the hash — never the plaintext, which is returned to the caller exactly ONCE inside
160	    /// the result's `plaintext` field and never re-derivable afterward.
161	    pub async fn issue(
162	        &self,
163	        actor: &Prn,
164	        sa_id: &PrincipalId,
165	        scope: TenancyNodeRef,
166	        expires_at: Option<DateTime<Utc>>,
167	        scope_actions: Vec<Action>,
168	        scope_roles: Vec<String>,
169	    ) -> Result<NewApiKey, TenancyError> {
170	        let sa = self.service_accounts.find(sa_id).await?.ok_or(TenancyError::NotFound)?;
171	
172	        self.authorize.check(actor, Action::IssueApiKey, &owner_resource_prn(&sa.account.owner)).await?;
173	
174	        let sa_grants = self.grants.list_by_principal(sa_id).await?;
175	        for grant in &sa_grants {
176	            self.authorize.check(actor, Action::GrantRole, &grant_scope_resource_prn(&grant.scope)).await?;
177	        }
178	
179	        let id = self.ids.new_api_key_id();
180	        let secret = self.entropy.new_secret();
181	        let hash = self.hasher.hash(&secret);
182	        let prefix = display_prefix(&self.config.key_prefix, id);
183	        let now = self.clock.now();
184	        let key = ApiKey {
185	            id,
186	            service_account_id: sa_id.clone(),
187	            scope,
188	            prefix,
189	            status: ApiKeyStatus::Active,
190	            expires_at: expires_at.or_else(|| self.default_expires_at(now)),
191	            last_used_at: None,
192	            created_at: now,
193	            revoked_at: None,
194	            scope_actions,
195	            scope_roles,
196	        };
197	        let plaintext = format_token(&self.config.key_prefix, id, &secret);
198	
199	        self.keys.issue(&key, &hash).await?;
200	        Ok(NewApiKey { key, plaintext })
201	    }
202	
203	    /// `expires_at.or_else`'s fallback: `now + config.default_expiry_days` if configured, else
204	    /// `None` (non-expiring until revoked — spec §11).
205	    fn default_expires_at(&self, now: DateTime<Utc>) -> Option<DateTime<Utc>> {
206	        self.config.default_expiry_days.map(|days| now + Duration::days(i64::from(days)))
207	    }
208	
209	    /// Revokes `key_id`: `NotFound` if it doesn't exist; finds its service account (`NotFound`
210	    /// if that's somehow gone too — belt-and-braces, the FK guarantees it exists in practice);
211	    /// authorizes `Action::RevokeApiKey` AT the SA's owner node; persists the revocation; then
212	    /// evicts the key's cached validation (mirrors `ServiceAccountService::archive`'s own
213	    /// cache-evict step, spec §9/D5 "revocation-vs-cache honesty" — without this, a just-revoked
214	    /// key that was already cached as valid would keep authenticating until its cache entry
215	    /// expires on its own).
216	    pub async fn revoke(&self, actor: &Prn, key_id: ApiKeyId) -> Result<(), TenancyError> {
217	        let (key, _hash) = self.keys.find_by_id(key_id).await?.ok_or(TenancyError::NotFound)?;
218	        let sa = self.service_accounts.find(&key.service_account_id).await?.ok_or(TenancyError::NotFound)?;
219	        self.authorize.check(actor, Action::RevokeApiKey, &owner_resource_prn(&sa.account.owner)).await?;
220	
221	        let now = self.clock.now();
222	        self.keys.revoke(key_id, now).await?;
223	        self.cache.evict(key_id).await;
224	        Ok(())
225	    }
226	
227	    /// Lists the API keys belonging to `sa_id`: `NotFound` if the SA doesn't exist; authorizes
228	    /// `Action::ListApiKeys` AT its owner node; delegates to `repo.list_by_service_account`.
229	    /// Never exposes a secret or hash — `ApiKey` carries neither field at all (structural: the
230	    /// hash lives only in `ApiKeyRepository::issue`/`find_by_id`'s separate `Vec<u8>`, and the
231	    /// plaintext is never persisted anywhere, module docs).
232	    pub async fn list(&self, actor: &Prn, sa_id: &PrincipalId, page: Page) -> Result<Vec<ApiKey>, TenancyError> {
233	        let sa = self.service_accounts.find(sa_id).await?.ok_or(TenancyError::NotFound)?;
234	        self.authorize.check(actor, Action::ListApiKeys, &owner_resource_prn(&sa.account.owner)).await?;
235	        Ok(self.keys.list_by_service_account(sa_id, page.limit, page.offset).await?)
236	    }
237	}
