284	    /// Seeds a service account row directly into the fake repo (bypassing
285	    /// `ServiceAccountService`, which lives in a sibling module and isn't this service's
286	    /// concern) and returns its principal id.
287	    fn seed_service_account(repo: &InMemoryServiceAccounts, owner: TenancyNodeRef, n: u128) -> PrincipalId {
288	        let id = PrincipalId::from_prn(Prn::build("iam", "", None, "principal", Uuid::from_u128(n)).unwrap());
289	        let now = Utc::now();
290	        let sa = ServiceAccount::new(id.clone(), owner, "ci-bot", now).unwrap();
291	        repo.accounts.lock().unwrap().insert(id.uuid(), sa);
292	        repo.statuses.lock().unwrap().insert(id.uuid(), PrincipalStatus::Active);
293	        id
294	    }
295	
296	    /// Seeds a `RoleGrant` directly into the fake store, mirroring `fakes.rs::owner_grant`'s
297	    /// own construction style.
298	    fn seed_role_grant(store: &InMemoryRoleGrants, n: u128, principal: &PrincipalId, role_key: &str, scope: GrantScope) {
299	        let id = Uuid::from_u128(n);
300	        let grant = RoleGrant {
301	            id,
302	            principal: principal.clone(),
303	            role_key: role_key.to_string(),
304	            scope,
305	            linked_policy_id: format!("grant:{id}"),
306	            created_at: Utc::now(),
307	        };
308	        store.0.lock().unwrap().insert(id, grant);
309	    }
310	
311	    #[tokio::test]
312	    async fn issue_returns_plaintext_once_and_persists_only_hash() {
313	        let owner = owner_org(1);
314	        let fake = FakeAuthorizer::default();
315	        fake.allow(Action::IssueApiKey, &owner_resource_prn(&owner));
316	        let (svc, keys, service_accounts, ..) = new_service(fake);
317	        let sa_id = seed_service_account(&service_accounts, owner, 100);
318	        let actor = actor_prn(1);
319	
320	        let new_key = svc.issue(&actor, &sa_id, owner_org(1), None, Vec::new(), Vec::new()).await.unwrap();
321	
322	        // The plaintext parses back to the persisted key's id.
323	        let parsed = parse_token(&ApiKeyConfig::default().key_prefix, &new_key.plaintext, 512).unwrap();
324	        assert_eq!(parsed.key_id, new_key.key.id);
325	
326	        // The persisted row is byte-identical to the one returned, and (structurally — `ApiKey`
327	        // carries no plaintext/secret field at all) can never leak the secret.
328	        let (stored_key, stored_hash) = keys.find_by_id(new_key.key.id).await.unwrap().unwrap();
329	        assert_eq!(stored_key, new_key.key);
330	
331	        // The stored hash is exactly `hasher.hash(secret)` for the secret embedded in the
332	        // returned plaintext.
333	        assert_eq!(stored_hash, FakeSecretHasher.hash(&parsed.secret));
334	    }
335	
336	    /// D15, THE key test: the SA holds an `org_admin` grant at `org_x`. `actor` is authorized
337	    /// for `IssueApiKey` at the SA's owner but was NEVER granted `GrantRole` at `org_x` — so
338	    /// `issue` must deny, `Forbidden`, and must not persist a key (an actor who could not grant
339	    /// `org_x`'s role to a third party must not be able to mint a key that wields it).
340	    #[tokio::test]
341	    async fn issue_denied_when_actor_cannot_grant_all_sa_roles() {
342	        let owner = owner_org(1);
343	        let org_x = owner_org(2);
344	        let fake = FakeAuthorizer::default();
345	        fake.allow(Action::IssueApiKey, &owner_resource_prn(&owner));
346	        // Deliberately NOT allowed: `GrantRole` @ org_x.
347	
348	        let (svc, keys, service_accounts, grants, _cache) = new_service(fake);
349	        let sa_id = seed_service_account(&service_accounts, owner, 200);
350	        seed_role_grant(&grants, 900, &sa_id, "org_admin", GrantScope::Node(org_x));
351	        let actor = actor_prn(1);
352	
353	        let err = svc.issue(&actor, &sa_id, owner_org(1), None, Vec::new(), Vec::new()).await.unwrap_err();
354	        assert_eq!(err, TenancyError::Forbidden);
355	        assert!(keys.0.lock().unwrap().is_empty(), "a D15-denied issue must not persist any key");
356	    }
