358	    /// The positive mirror of the D15 test: `actor` dominates EVERY grant the SA holds (as well
359	    /// as `IssueApiKey` at the owner) — issuance must succeed.
360	    #[tokio::test]
361	    async fn issue_allowed_when_actor_dominates_all_sa_grants() {
362	        let owner = owner_org(1);
363	        let org_x = owner_org(2);
364	        let fake = FakeAuthorizer::default();
365	        fake.allow(Action::IssueApiKey, &owner_resource_prn(&owner));
366	        fake.allow(Action::GrantRole, &owner_resource_prn(&org_x));
367	
368	        let (svc, keys, service_accounts, grants, _cache) = new_service(fake);
369	        let sa_id = seed_service_account(&service_accounts, owner, 300);
370	        seed_role_grant(&grants, 901, &sa_id, "org_admin", GrantScope::Node(org_x));
371	        let actor = actor_prn(1);
372	
373	        let new_key = svc.issue(&actor, &sa_id, owner_org(1), None, Vec::new(), Vec::new()).await.unwrap();
374	        assert_eq!(new_key.key.service_account_id, sa_id);
375	        assert!(keys.0.lock().unwrap().contains_key(&new_key.key.id));
376	    }
377	
378	    #[tokio::test]
379	    async fn issue_missing_service_account_is_not_found() {
380	        let (svc, ..) = new_service(FakeAuthorizer::default());
381	        let missing = PrincipalId::from_prn(Prn::build("iam", "", None, "principal", Uuid::from_u128(999)).unwrap());
382	        let actor = actor_prn(1);
383	
384	        let err = svc.issue(&actor, &missing, owner_org(1), None, Vec::new(), Vec::new()).await.unwrap_err();
385	        assert_eq!(err, TenancyError::NotFound);
386	    }
387	
388	    #[tokio::test]
389	    async fn revoke_authorizes_and_evicts_cache() {
390	        let owner = owner_org(1);
391	        let fake = FakeAuthorizer::default();
392	        fake.allow(Action::IssueApiKey, &owner_resource_prn(&owner));
393	        fake.allow(Action::RevokeApiKey, &owner_resource_prn(&owner));
394	        let (svc, keys, service_accounts, _grants, cache) = new_service(fake);
395	        let sa_id = seed_service_account(&service_accounts, owner, 400);
396	        let actor = actor_prn(1);
397	
398	        let new_key = svc.issue(&actor, &sa_id, owner_org(1), None, Vec::new(), Vec::new()).await.unwrap();
399	        cache
400	            .put(
401	                new_key.key.id,
402	                &CachedValidation {
403	                    principal_id: sa_id.clone(),
404	                    sa_status: PrincipalStatus::Active,
405	                    expires_at: None,
406	                    key_hash: b"hash".to_vec(),
407	                },
408	            )
409	            .await;
410	        assert!(cache.get(new_key.key.id).await.is_some(), "sanity: the cache entry exists before revoke");
411	
412	        svc.revoke(&actor, new_key.key.id).await.unwrap();
413	
414	        // The security-critical part: the cached validation is gone.
415	        assert!(cache.get(new_key.key.id).await.is_none(), "revoke must evict the key's cached validation");
416	        // And the repo call actually happened: the stored row flips to Revoked.
417	        let (stored_key, _) = keys.find_by_id(new_key.key.id).await.unwrap().unwrap();
418	        assert_eq!(stored_key.status, ApiKeyStatus::Revoked);
419	    }
420	
421	    #[tokio::test]
422	    async fn revoke_denied_without_authz_then_succeeds_once_authorized() {
423	        let owner = owner_org(1);
424	        let fake = FakeAuthorizer::default();
425	        fake.allow(Action::IssueApiKey, &owner_resource_prn(&owner));
426	        // `RevokeApiKey` never allowed yet.
427	        let (svc, keys, service_accounts, ..) = new_service(fake.clone());
428	        let sa_id = seed_service_account(&service_accounts, owner.clone(), 401);
429	        let actor = actor_prn(1);
430	        let new_key = svc.issue(&actor, &sa_id, owner.clone(), None, Vec::new(), Vec::new()).await.unwrap();
431	
432	        assert_eq!(svc.revoke(&actor, new_key.key.id).await.unwrap_err(), TenancyError::Forbidden);
433	        let (still_active, _) = keys.find_by_id(new_key.key.id).await.unwrap().unwrap();
434	        assert_eq!(still_active.status, ApiKeyStatus::Active);
435	
436	        fake.allow(Action::RevokeApiKey, &owner_resource_prn(&owner));
437	        svc.revoke(&actor, new_key.key.id).await.unwrap();
438	        let (revoked, _) = keys.find_by_id(new_key.key.id).await.unwrap().unwrap();
439	        assert_eq!(revoked.status, ApiKeyStatus::Revoked);
440	    }
