442	    #[tokio::test]
443	    async fn revoke_missing_key_is_not_found() {
444	        let (svc, ..) = new_service(FakeAuthorizer::default());
445	        let actor = actor_prn(1);
446	        let missing = ApiKeyId::from_uuid(Uuid::from_u128(12345));
447	        assert_eq!(svc.revoke(&actor, missing).await.unwrap_err(), TenancyError::NotFound);
448	    }
