42	use crate::adapters::api_keys::ApiKeyValidationCache;
43	use crate::application::authorize::Authorize;
44	use crate::application::error::TenancyError;
45	use crate::application::pagination::Page;
46	use paigasus_iam_core::{
47	    Action, ApiKeyRepository, Clock, IdGenerator, Principal, PrincipalId, PrincipalKind, PrincipalStatus, ServiceAccount, ServiceAccountRecord, ServiceAccountRepository, TenancyNodeRef,
48	};
49	use paigasus_kernel::Prn;
50	use std::sync::Arc;
51	
52	/// The `Prn` a service account's owner node represents as an authorization *resource* —
53	/// mirrors `roles.rs::scope_resource_prn`'s node arms exactly (no `Root` arm: a service
54	/// account's owner is always a concrete tenancy node, `ck_service_account_owner`).
55	fn owner_resource_prn(owner: &TenancyNodeRef) -> Prn {
56	    match owner {
57	        TenancyNodeRef::Organization(id) => id.prn().clone(),
58	        TenancyNodeRef::Team(id) => id.prn().clone(),
59	        TenancyNodeRef::Project(id) => id.prn().clone(),
60	    }
61	}
62	
63	/// Service-account lifecycle use cases. `keys`/`cache` are shared `Arc<dyn ...>` handles
64	/// (module docs); `repo`/`ids`/`clock` stay generic-DI.
65	#[derive(Clone)]
66	pub struct ServiceAccountService<R, I, C> {
67	    repo: R,
68	    keys: Arc<dyn ApiKeyRepository>,
69	    cache: Arc<dyn ApiKeyValidationCache>,
70	    authorize: Authorize,
71	    ids: I,
72	    clock: C,
73	}
74	
75	impl<R, I, C> ServiceAccountService<R, I, C>
76	where
77	    R: ServiceAccountRepository,
78	    I: IdGenerator,
79	    C: Clock,
80	{
81	    pub fn new(repo: R, keys: Arc<dyn ApiKeyRepository>, cache: Arc<dyn ApiKeyValidationCache>, authorize: Authorize, ids: I, clock: C) -> Self {
82	        Self {
83	            repo,
84	            keys,
85	            cache,
86	            authorize,
87	            ids,
88	            clock,
89	        }
90	    }
91	
92	    /// Creates a service account owned by `owner`. Authorizes `Action::CreateServiceAccount`
93	    /// AT `owner` BEFORE minting anything — an unauthorized actor never causes an id to be
94	    /// consumed or a row to be written. `name` validation (`ServiceAccount::new`) runs after
95	    /// the authz check, mirroring `RoleService::grant`'s "check first" posture: a caller who
96	    /// isn't allowed to create here shouldn't learn whether their proposed name would even be
97	    /// valid. The returned record's `status` is `Active` WITHOUT a re-query — a freshly created
98	    /// SA's principal is minted `Active` right above, so there's nothing a follow-up read could
99	    /// tell us that we don't already know.
100	    pub async fn create(&self, actor: &Prn, owner: TenancyNodeRef, name: &str) -> Result<ServiceAccountRecord, TenancyError> {
101	        self.authorize.check(actor, Action::CreateServiceAccount, &owner_resource_prn(&owner)).await?;
102	
103	        let id = self.ids.new_service_account_id();
104	        let now = self.clock.now();
105	        let principal = Principal::new(id.clone(), PrincipalKind::ServiceAccount, PrincipalStatus::Active, now, now);
106	        let sa = ServiceAccount::new(id, owner, name, now)?;
107	        self.repo.create(&principal, &sa).await?;
108	        Ok(ServiceAccountRecord {
109	            account: sa,
110	            status: PrincipalStatus::Active,
111	        })
112	    }
113	
114	    /// Fetches a service account by principal id. `NotFound` if absent — checked BEFORE
115	    /// authorization since the resource to authorize against (the SA's owner node) can only be
116	    /// learned by reading the row first (mirrors `archive`'s own order, brief).
117	    pub async fn get(&self, actor: &Prn, id: &PrincipalId) -> Result<ServiceAccountRecord, TenancyError> {
118	        let record = self.repo.find(id).await?.ok_or(TenancyError::NotFound)?;
119	        self.authorize.check(actor, Action::GetServiceAccount, &owner_resource_prn(&record.account.owner)).await?;
120	        Ok(record)
121	    }
122	
123	    /// Lists service accounts owned by `owner`, `ORDER BY created_at, id` (rule 9, delegated to
124	    /// the repo). Authorizes `Action::ListServiceAccounts` AT `owner` directly — unlike `get`,
125	    /// the resource is already known from the caller-supplied `owner`, no lookup needed first.
126	    pub async fn list(&self, actor: &Prn, owner: &TenancyNodeRef, page: Page) -> Result<Vec<ServiceAccountRecord>, TenancyError> {
127	        self.authorize.check(actor, Action::ListServiceAccounts, &owner_resource_prn(owner)).await?;
128	        Ok(self.repo.list_by_owner(owner, page.limit, page.offset).await?)
129	    }
130	
131	    /// Archives (disables) a service account: `NotFound` if it doesn't exist; authorizes
132	    /// `Action::ArchiveServiceAccount` AT its OWNER node (found via the lookup above, since the
133	    /// caller only supplies the SA's own id); disables the underlying `Principal` (D16: status
134	    /// lives there, not on `ServiceAccount`); then evicts every one of the SA's cached API-key
135	    /// validations (`keys.list_ids_by_service_account` -> `cache.evict` per id) — the
136	    /// SECURITY-CRITICAL step (module docs): without it, a disabled SA's already-cached keys
137	    /// would keep authenticating until their cache entries expire on their own.
138	    pub async fn archive(&self, actor: &Prn, id: &PrincipalId) -> Result<(), TenancyError> {
139	        let record = self.repo.find(id).await?.ok_or(TenancyError::NotFound)?;
140	        self.authorize.check(actor, Action::ArchiveServiceAccount, &owner_resource_prn(&record.account.owner)).await?;
141	
142	        self.repo.set_principal_status(id, PrincipalStatus::Disabled).await?;
143	
144	        let key_ids = self.keys.list_ids_by_service_account(id).await?;
145	        for key_id in key_ids {
146	            self.cache.evict(key_id).await;
147	        }
148	        Ok(())
149	    }
150	}
