=== IntrospectApiKey request/response messages ===
message IntrospectApiKeyRequest {
  string token = 1;
}
message IntrospectApiKeyResponse {
  string principal_prn = 1;
  string status = 2; // principal status
  string key_id = 3;
  google.protobuf.Timestamp expires_at = 4;
  repeated Membership memberships = 5; // reuse tenancy message
  repeated RoleGrantRef role_grants = 6;
}

=== IsAuthorized request/response ===
message IsAuthorizedRequest {
  string principal_prn = 1;
  string action = 2;
  string resource_prn = 3;
  map<string, string> context = 4;
}
message IsAuthorizedResponse {
  bool allowed = 1;
  repeated string determining_policies = 2;
  string reason = 3;
}

=== ApiKey scope fields (what the key is scoped to) ===
message ApiKey {
  string id = 1;
  string service_account_prn = 2;
  string scope_prn = 3;
  string prefix = 4;
  ApiKeyStatus status = 5;
  google.protobuf.Timestamp expires_at = 6;
  google.protobuf.Timestamp last_used_at = 7;
  repeated string scope_actions = 8; // stored, unenforced in v1
  repeated string scope_roles = 9; // stored, unenforced in v1
  paigasus.common.v1.AuditMetadata audit = 10;
}

